module fsm(
    input IN, CLK, RST,
    output reg MATCH
);
// State declaration
parameter s0 = 3'b000;
parameter s1 = 3'b001;
parameter s2 = 3'b010;
parameter s3 = 3'b011;
parameter s4 = 3'b100;
parameter s5 = 3'b101;
// State register
reg [2:0] ST_cr, ST_ns;
// Next state logic
always @(*) begin
    case(ST_cr)
        s0: begin
            if(IN == 1) 
                ST_ns = s1;
            else 
                ST_ns = s0;
        end
        s1: begin
            if(IN == 1) 
                ST_ns = s1;
            else 
                ST_ns = s2;
        end
        s2: begin
            if(IN == 1) 
                ST_ns = s1;
            else 
                ST_ns = s3;
        end
        s3: begin
            if(IN == 1) 
                ST_ns = s4;
            else 
                ST_ns = s0;
        end
        s4: begin
            if(IN == 1) 
                ST_ns = s5;
            else 
                ST_ns = s2;
        end
        s5: begin
            if(IN == 1) 
                ST_ns = s1;
            else 
                ST_ns = s2;
        end
        default: ST_ns = s0;
    endcase
end
// Current state update
always @(posedge CLK or posedge RST) begin
    if(RST) begin
        ST_cr <= s0;
    end else begin
        ST_cr <= ST_ns;
    end
end
// Output logic
always @(*) begin
    if(RST) begin
        MATCH = 1'b0;
    end else if(ST_cr == s4 && IN == 1) begin
        MATCH = 1'b1;
    end else begin
        MATCH = 1'b0;
    end
end
endmodule
